#[test]
fn self_field_is_not_the_shadowing_local() {
    let src = concat!(
        "struct Bytes { src: Vec<u8> }\n",
        "impl Bytes {\n",
        "    fn reindent(&self) {\n",
        "        let mut src = Vec::with_capacity(self.src.len());\n",
        "        let _ = vec![self.src.len()];\n",
        "        src.push(1);\n",
        "    }\n",
